package autogradesys.validation;

import autogradesys.cli.TextColor;

/**
 * One thing the validation did or could not do for a submission.
 *
 * @param student Name of the student's folder when the event happened.
 * @param type    What happened.
 * @param path    Where it happened, relative to the submissions folder.
 * @param message A short description.
 */
// Generated by Claude (Anthropic); reviewed and adapted by the team
/**
 * Stores the student, event type, path, and user-facing validation message.
 */
public record ValidationEvent(String student, Type type, String path, String message) {

    /**
     * What happened. The constant's flag says whether the problem was fixed
     * automatically.
     */
    public enum Type {
        // Fixed automatically.
        FOLDER_FLATTENED(true),
        FOLDER_RENAMED(true),
        HEADER_ADDED(true),
        HEADER_CORRECTED(true),
        ARCHIVE_EXTRACTED(true),
        IGNORED_JUNK(true),
        ITEM_RESTORED(true),
        // Still needs the instructor's attention.
        USERNAME_UNREGISTERED(false),
        USERNAME_DUPLICATE(false),
        TYPO_DECLINED(false),
        HEADER_FOREIGN(false),
        ARCHIVE_FAILED(false),
        COPY_FAILED(false),
        ITEM_MISSING(false),
        FIX_FAILED(false),
        RESOURCE_REPLACED(true),
        RESOURCE_REMOVED(true),
        RESOURCES_SYNCHRONISED(true),
        RESOURCE_SYNC_FAILED(false);

        private final boolean fixed;

        /**
         * Creates one event type.
         *
         * @param fixed true if this kind of event means the problem was repaired automatically; false if the instructor still has to act
         */
        Type(boolean fixed) {
            this.fixed = fixed;
        }

        /**
         * Tells whether this kind of event is an automatic repair.
         *
         * @return true for an automatic fix; false for a problem that still needs attention
         */
        public boolean isFixed() {
            return fixed;
        }

        /**
         * Builds the label shown in front of an event in the console.
         *
         * @return the type's name in square brackets, green for a fix and red for a problem
         */
        public String getTagWithColor() {
            TextColor color = this.isFixed() ? TextColor.SUCCESS : TextColor.ERROR;
            return color.getActionTag(this.toString());
        }
    }

    /**
     * Tells whether this event was an automatic repair.
     *
     * @return true if its type is a fix; false if the problem remains
     */
    public boolean fixed() {
        return type.isFixed();
    }

    /**
     * Builds the console line for this event in the format
     *
     * <pre>
     * "  [TYPE] path/of/files - log message"
     * </pre>
     *
     * @return the line, with the type tag coloured
     */
    public String getLogMessage() {
        return "  " + this.type.getTagWithColor() + " " + this.path() + " - " + this.message();
    }
}
